 wb=load_workbook(input_dir/"Termination_Tracker.xlsx",read_only=True,data_only=True);ws=wb["Pending Terminations"];headers=[c.value for c in ws[1]];rows=[dict(zip(headers,values)) for values in ws.iter_rows(min_row=2,values_only=True)]
 messages=[{"id":str(m.get("X-AutomationBench-Message-ID")),"from":str(m.get("From")),"subject":str(m.get("Subject")),"body":body(m)} for m in mailbox.mbox(input_dir/"Termination_Procedure.mbox",create=False)]
