def derive(rows):
 decisions=[]
 for row in rows:
  if isinstance(row["Last Day"],datetime):row["Last Day"]=row["Last Day"].date()
  rescinded="rescinded" in str(row["Notes"]).lower();already=row["Status"]=="Processed";pto=str(row["PTO Balance"] or "").strip();unknown=pto in ("","N/A","TBD")
