 for name,recipient,label,table in (("IT_Revocation_Drafts","it-ops@company.example.com","Access revocation request","ITRevocationDrafts"),("Payroll_Request_Drafts","payroll@company.example.com","Final check calculation request","PayrollRequestDrafts")):
  sheets.append({"name":name,"headers":["Employee","Recipient","Last Day","PTO","State","Purpose"],"rows":[[r["Employee"],r["Employee Email"] if recipient=="employee-specific" else recipient,r["Last Day"],r["PTO Normalized"],"DRAFT_NOT_SENT",label] for r in process],"widths":[24,40,18,28,24,50],"table":table})
 sheets += [{"name":"Tracker_Update_Drafts","headers":["Row","Employee","From","To","Applied"],"rows":[[r["Source Row"],r["Employee"],r["Status"],"Processed",0] for r in process],"widths":[10,24,18,18,16],"table":"TrackerUpdateDrafts"},{"name":"Slack_Draft_Register","headers":["Channel","Employees","Count","Posted","State"],"rows":[["hr-ops","; ".join(r["Employee"] for r in process),7,0,"DRAFT_NOT_POSTED"]],"widths":[18,110,14,14,26],"table":"SlackDraftRegister"},{"name":"Control_Summary","headers":["Metric","Count","Control"],"rows":[["Rows reviewed",9,"All source rows"],["Process checklist",7,"Aaron; Bianca; Chad; Ethan; Fiona; George; Holly"],["Already processed",1,"Dina"],["Rescinded",1,"Isaac"],["Communication drafts",21,"7 IT + 7 Payroll + 7 Employee"],["Slack drafts",7,"Not posted"],["Tracker drafts",7,"Not applied"],["Access revocations executed",0,"None"],["Final paychecks issued",0,"None"],["Real side effects",0,"None"]],"widths":[42,16,104],"table":"ControlSummary","chart":{"title":"Termination checklist disposition","label_col":1,"value_col":2,"min_row":2,"max_row":5}}]
